"""Independent music-only annotation and blinded R58 quality comparison preparation; zero labels."""
from pathlib import Path
import json,secrets,subprocess
import numpy as np
from dunhuang.research.complete_r36.core import read,write,sha
from dunhuang.research.strong_baseline_r52.view import finish,encode
from dunhuang.research.paired_benchmark_r59.common import ROOT,fresh

def main():
 root=fresh(ROOT/'quality_review');viewer=fresh(root/'viewer');music=fresh(root/'music');old=Path('outputs/execution_planning_r58_01');d=read(old/'controls/result.json');z=np.load(old/'controls/arrays.npz');parent=read('outputs/music_structure_r56_02/controls/result.json');seal=read(old/'artifacts_manifest.json')['files']
 for name in ('controls/result.json','controls/arrays.npz'):assert sha(old/name)==next(r['sha256'] for r in seal if r['path']==name)
 rng=np.random.default_rng(secrets.randbits(63));cases=[];admin=[];audio=[];pairs=[('B0','B1'),('B0','C1'),('B0','C2'),('B1','C1'),('B1','C2'),('C1','C2')]
 binding=read(old/'main/result.json')['binding']['parent'];tracks=binding['music']
 for song in range(3):
  src=Path(tracks[song]['path']);assert sha(src)==parent['music'][str(song)]['audio_sha256'];name=f'audio{song}.m4a';subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-i',str(src),'-c:a','aac','-b:a','160k',str(viewer/name)],check=True);audio.append(dict(blind_item_id='M'+str(song+1).zfill(2),file='../viewer/'+name,raw_audio_sha256=sha(src),media_sha256=sha(viewer/name),frames=int(parent['music'][str(song)]['frames'])))
  for pair in pairs:
   order=list(pair)
   if rng.random()<.5:order.reverse()
   item='Q'+str(len(cases)+1).zfill(3);N=int(parent['music'][str(song)]['frames']);methods=[dict(name=label,data=encode(z[f'song{song}_{arm}_P']),jerk=[]) for label,arm in zip(('A','B'),order)];cases.append(dict(label=item+' · 音乐'+str(song+1),frames=N,origin=0,audio=name,methods=methods,meta=dict(scope='同音乐/相机/尺度。只评价自然流畅、音乐协调、整曲变化与重复；允许差不多/无法判断。准备页，人类记录0；22关节局部身体，Root/接触未知。',regions=[],blind_item_id=item)));admin.append(dict(blind_item_id=item,song=song,A=order[0],B=order[1],raw_audio_sha256=sha(src)))
 order=rng.permutation(len(cases));cases=[cases[int(i)] for i in order];finish(viewer,cases,z['parents']);page=(viewer/'index.html').read_text(encoding='utf8').replace('R52','R59独立质量盲评准备').replace('保留 Heuristic 强基线；生成比较同一完整来源与几何基线，修复评价时间坐标。来源阶段为观测运动学代理，世界 Root／接触及 Native24 尚未取得完整资格。','隐藏B0/B1/C1/C2身份，比较音乐协调、自然流畅及整曲变化。允许差不多／无法判断；不在本轮反向调参。').replace('来源、条件与评价详情','盲审项目详情');(viewer/'index.html').write_bytes(page.encode());write(viewer/'protocol.json',dict(cases=len(cases),files=[dict(name=p.name,bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(viewer.iterdir()) if p.name!='protocol.json']))
 (music/'data.js').write_bytes(('window.MUSIC_ITEMS='+json.dumps(audio,ensure_ascii=False)+';').encode());(music/'index.html').write_bytes(MUSIC_PAGE.encode());write(root/'admin_mapping.json',dict(items=admin,private_mapping=True));write(root/'protocol.json',dict(status='PREPARATION_ONLY',independent_records=0,music_items=3,quality_pairs=18,human_reviewed=False,require_independent_reviewers=2,conflicts_retained=True,UNKNOWN_allowed=True,metrics_preference_agreement='NOT_EVALUABLE',scores_used_for_weight_tuning=False,admin_mapping_public=False,review_tasks=['MUSIC_ONLY_BOUNDARIES_ACCENTS_REPETITIONS_UNSURE','MUSIC_COORDINATION','NATURALNESS','WHOLE_SONG_VARIATION'],source_manifest_sha256=sha(old/'artifacts_manifest.json')));print('R59_QUALITY_PREPARED',len(cases))

MUSIC_PAGE=r'''<!doctype html><html lang="zh"><meta charset="utf-8"><style>body{max-width:1100px;margin:30px auto;background:#f4f1e8;color:#173e36;font:18px system-ui}button,input,select{font:inherit;padding:7px;margin:5px}audio{width:100%}pre{white-space:pre-wrap}</style><h1>R59 · 只听音乐的独立结构标注准备</h1><p>不展示动作、自动峰、方法分数或模型预测。标记可听见的边界、明显重音、重复段和无法判断区间；允许分歧。本页面不预置人工标签，也不自动提交记录。</p><select id="item"></select><audio id="audio" controls></audio><p id="time"></p><p><button id="boundary">音乐边界</button><button id="accent">明显重音</button><button id="repeatStart">重复段起点</button><button id="repeatEnd">重复段终点</button><button id="unsureStart">无法判断起点</button><button id="unsureEnd">无法判断终点</button><button id="undo">撤回最后一项</button></p><p><label>审核人编号 <input id="reviewer"></label><label>身份登记引用 <input id="roster"></label></p><button id="export">导出本人记录</button><p id="message">PREPARATION_ONLY · 尚未导出记录</p><pre id="events"></pre><script src="data.js"></script><script>
const $=id=>document.getElementById(id),audio=$('audio'),marks={};MUSIC_ITEMS.forEach((x,i)=>{$('item').add(new Option(x.blind_item_id,i));marks[x.blind_item_id]=[]});function row(){return MUSIC_ITEMS[+$('item').value]}function show(){$('time').textContent='当前 '+audio.currentTime.toFixed(3)+' 秒';$('events').textContent=JSON.stringify(marks[row().blind_item_id],null,2)}function load(){audio.pause();audio.src=row().file;show()}$('item').onchange=load;audio.ontimeupdate=show;['boundary','accent','repeatStart','repeatEnd','unsureStart','unsureEnd'].forEach(type=>$(type).onclick=()=>{marks[row().blind_item_id].push({type,seconds:audio.currentTime,frame30:Math.round(audio.currentTime*30)});show()});$('undo').onclick=()=>{marks[row().blind_item_id].pop();show()};$('export').onclick=()=>{if(!$('reviewer').value.trim()||!$('roster').value.trim()){ $('message').textContent='请填写真实审核人编号和身份登记引用；不会生成虚假身份。';return}const records=MUSIC_ITEMS.filter(x=>marks[x.blind_item_id].length).map(x=>({...x,events:marks[x.blind_item_id]}));if(!records.length){$('message').textContent='尚无标注，不导出空白人工记录。';return}const value={protocol:'R59_MUSIC_ONLY_V1',reviewer_id:$('reviewer').value.trim(),reviewer_roster_ref:$('roster').value.trim(),reviewed_at:new Date().toISOString(),records};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.download='r59_music_review.json';a.click();URL.revokeObjectURL(a.href);$('message').textContent='已导出本人原始意见；仍需独立复核与分歧处理，不能自动成为真值。'};load();</script></html>'''
if __name__=='__main__':main()
